create table public.rental_adjustments (id uuid default gen_random_uuid() not null, organization_id uuid default current_organization_id() not null, contract_id uuid not null, index_name text not null, index_percent numeric(10,6) not null, previous_rent numeric(14,2) not null, new_rent numeric(14,2) not null, effective_date date not null, notes text, created_by uuid default auth.uid(), created_at timestamptz default now() not null);
create table public.rental_cases (id uuid default gen_random_uuid() not null, property_id uuid not null, lead_id uuid, stage text default 'available' not null, stage_entered_at timestamptz default now() not null, active boolean default true not null, created_at timestamptz default now() not null, updated_at timestamptz default now() not null);
create table public.rental_charges (id uuid default gen_random_uuid() not null, organization_id uuid default current_organization_id() not null, contract_id uuid not null, reference_month date not null, due_date date not null, base_rent numeric(14,2) default 0 not null, tenant_charges numeric(14,2) default 0 not null, owner_expenses numeric(14,2) default 0 not null, discount numeric(14,2) default 0 not null, penalty numeric(14,2) default 0 not null, interest numeric(14,2) default 0 not null, amount_due numeric(14,2) default 0 not null, amount_paid numeric(14,2) default 0 not null, status text default 'due' not null, paid_at date, payment_method text, notes text, created_at timestamptz default now() not null, updated_at timestamptz default now() not null);
create table public.rental_collection_actions (id uuid default gen_random_uuid() not null, organization_id uuid default current_organization_id() not null, charge_id uuid not null, contacted_at timestamptz default now() not null, channel text default 'whatsapp' not null, notes text, agreement_text text, installment_plan text, next_contact_at timestamptz, created_by uuid default auth.uid(), created_at timestamptz default now() not null);
create table public.rental_contract_tenants (id uuid default gen_random_uuid() not null, organization_id uuid default current_organization_id() not null, contract_id uuid not null, tenant_id uuid not null, role text default 'co_tenant' not null, signed boolean default false not null, created_at timestamptz default now() not null);
create table public.rental_contracts (id uuid default gen_random_uuid() not null, organization_id uuid default current_organization_id() not null, code text not null, property_id uuid not null, lead_id uuid, assigned_to uuid, assigned_by uuid, assigned_at timestamptz, status text default 'analysis' not null, tenant_name text not null, tenant_document text, tenant_whatsapp text, tenant_email text, co_tenants text, owner_name text, owner_whatsapp text, owner_email text, start_date date, end_date date, signed_at timestamptz, move_in_at timestamptz, move_out_at timestamptz, monthly_rent numeric(14,2), due_day integer default 10 not null, administration_fee_percent numeric(7,4) default 0, placement_fee_value numeric(14,2) default 0, condominium_amount numeric(14,2) default 0, property_tax_amount numeric(14,2) default 0, property_tax_payer text default 'tenant' not null, guarantee_type text default 'none' not null, guarantee_value numeric(14,2), guarantee_notes text, adjustment_index text default 'ipca' not null, adjustment_percent numeric(8,4), next_adjustment_date date, utilities_notes text, notes text, created_at timestamptz default now() not null, updated_at timestamptz default now() not null);;
